#include <iostream>
#include <memory>

class B;

class A {
public:
    std::shared_ptr<B> b_ptr;
    ~A() { std::cout << "A destroyed\n"; }
};

class B {
public:
    // Using a weak_ptr breaks the ownership cycle
    std::weak_ptr<A> a_ptr;
    ~B() { std::cout << "B destroyed\n"; }
};

int main() {
    auto a = std::make_shared<A>();
    auto b = std::make_shared<B>();
    a->b_ptr = b;
    b->a_ptr = a;

    // Using weak_ptr from b to observe a
    std::weak_ptr<A> weak_a = b->a_ptr;

    // Check if object exists before use
    if (auto shared_a = weak_a.lock()) {
        std::cout << "A still exists. Use count: " << shared_a.use_count() << "\n";
    } else {
        std::cout << "A has been destroyed.\n";
    }

    // Reset 'a', the last owning pointer.
    a.reset();
    std::cout << "'a' shared_ptr has been reset.\n";

    // Try to lock again, it will fail.
    if (auto shared_a = weak_a.lock()) {
        std::cout << "This will not be printed.\n";
    } else {
        std::cout << "A no longer exists; weak_ptr is expired.\n";
    }

    // Constructing from an expired weak_ptr throws an exception.
    try {
        std::shared_ptr<A> p(weak_a);
    } catch (const std::bad_weak_ptr& e) {
        std::cout << "Exception caught: " << e.what() << "\n";
    }

    return 0; // b is destroyed here, as a->b_ptr is gone.
}
